import api from "./axiosInstance";
import { ApiResponse, PaginationParams, TransactionHistoryData } from "@/types";

export interface TransactionData {
  id?: number;
  category_id: number;
  type: "INCOME" | "EXPENSE";
  amount: number;
  transaction_date: string;
  description?: string;
}

export interface TransactionListParams extends PaginationParams {
  type?: "INCOME" | "EXPENSE";
  category_id?: number;
  wallet_id?: number;
  is_pending?: "Y" | "N";
  startDate?: string;
  endDate?: string;
}

